namespace AIDesignStudio.Application.Storage;

/// <summary>
/// Blob storage port. Implemented locally on the filesystem for development and
/// by Azure Blob Storage in deployed environments.
///
/// Keys are generated by <see cref="BuildKey"/>, never accepted from a client:
/// a client-supplied key would be a path-traversal and cross-tenant read primitive.
/// </summary>
public interface IAssetStorage
{
    /// <summary>Backend identifier for diagnostics, e.g. <c>local-filesystem</c>.</summary>
    string BackendId { get; }

    Task<StoredAsset> SaveAsync(
        string storageKey,
        Stream content,
        string contentType,
        CancellationToken cancellationToken);

    Task<Stream> OpenReadAsync(string storageKey, CancellationToken cancellationToken);

    Task<bool> ExistsAsync(string storageKey, CancellationToken cancellationToken);

    Task DeleteAsync(string storageKey, CancellationToken cancellationToken);

    /// <summary>
    /// Builds the opaque storage key for an asset. Organization id is the leading
    /// path segment so that a mis-scoped query cannot silently cross tenants.
    /// </summary>
    static string BuildKey(Guid organizationId, Guid projectId, Guid assetId, string extension)
    {
        var ext = string.IsNullOrWhiteSpace(extension)
            ? string.Empty
            : "." + extension.TrimStart('.').ToLowerInvariant();

        return $"org/{organizationId:N}/project/{projectId:N}/asset/{assetId:N}{ext}";
    }
}

/// <param name="StorageKey">Key the bytes were written under.</param>
/// <param name="SizeBytes">Byte count actually written.</param>
/// <param name="ContentHash">Lowercase hex SHA-256 of the written bytes.</param>
public sealed record StoredAsset(string StorageKey, long SizeBytes, string ContentHash);

/// <summary>
/// Thrown when a storage key is syntactically invalid or escapes its container.
/// </summary>
public sealed class InvalidStorageKeyException(string key)
    : Exception($"Invalid storage key: '{key}'.");
